# Generated by build.py from recipe.yml for recipe http-compare-a-good-and-a-bad-request. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.csv'), "id,total`n1,40`n")
[IO.File]::WriteAllText((Join-Path $PWD 'compare.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Puts the first request surl answered 200 beside the last one it answered 400, from its`n# verbose log, prints the lines that differ, then the reason surl gave for the 400.`n# Run: sh compare.sh [surl.log]    (needs a POSIX shell: Git Bash on Windows)`nlog=`${1:-surl.log}`n`n# The log is whole once every exchange that opened has ended: wait for that, at most 10 s.`ntries=0`nuntil [ `"`$(grep -c ' opened: ' `"`$log`")`" -eq `"`$(grep -c ' ended; ' `"`$log`")`" ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 50 ]; then echo `"the exchanges in `$log did not end within 10 s`"; exit 1; fi`n  sleep 0.2`ndone`n`n# Which exchanges, by the status lines surl sent: #N is the exchange's number.`ngood=`$(grep ' > HTTP/1.1 200 ' `"`$log`" | head -n 1 | cut -d' ' -f1)`nbad=`$(grep ' > HTTP/1.1 400 ' `"`$log`" | tail -n 1 | cut -d' ' -f1)`nif [ -z `"`$good`" ] || [ -z `"`$bad`" ]; then echo `"`$log has no 200 and 400 to compare`"; exit 1; fi`necho `"good: exchange `$good, answered 200`"`necho `"bad:  exchange `$bad, answered 400`"`n`n# Each request as surl read it: its '<' lines, without the prefix and the CR LF shown as text.`ngrep `"^`$good < `" `"`$log`" | sed -e 's/^#[0-9]* < //' -e 's/\\r\\n`$//' > good.txt`ngrep `"^`$bad < `" `"`$log`" | sed -e 's/^#[0-9]* < //' -e 's/\\r\\n`$//' > bad.txt`ndiff good.txt bad.txt`n`n# Why surl refused it, in its own words.`ngrep `"^`$bad \* .*answered 400`" `"`$log`" | sed 's/^#[0-9]* \* /why:  /'`nexit 0`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh compare.sh surl.log } finally { Stop-Process $server0 }
